INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('707485e8-6dc0-4b5e-9dc4-f69cf221bcf0', '150f78d3-019b-40c0-962e-a83576309ea5', 3, 'A Pureza da Intenção', NULL, '{"intro": "Muitas vezes fazemos coisas boas por motivos ego\u00edstas.", "prayer": "Pe\u00e7a um cora\u00e7\u00e3o puro e reto.", "practice": "Escolha uma tarefa e a realize com a inten\u00e7\u00e3o de agradar a Deus.", "reflection": "Faze o que fazes, por amor e s\u00f3 por amor.", "journal_prompt": "Por que voc\u00ea faz o que faz?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;